import React, { useState, useEffect } from 'react';
import { QrReader } from 'react-qr-reader';
import { 
  getJugadores, getEntrenamientos, getPartidos,
  updateAsistenciaEntrenamiento, updateAsistenciaPartido,
  getPagos, getAsistenciaEntrenamientos, getAsistenciaPartidos,
  getCurrentUser, registrarPago
} from '../../database/db';
import './EscanerQR.css';

function EscanerQR() {
  const [scanResult, setScanResult] = useState('');
  const [showScanner, setShowScanner] = useState(false);
  const [jugadores, setJugadores] = useState([]);
  const [entrenamientos, setEntrenamientos] = useState([]);
  const [partidos, setPartidos] = useState([]);
  const [pagos, setPagos] = useState([]);
  const [eventoSeleccionado, setEventoSeleccionado] = useState({ tipo: 'entrenamiento', id: null });
  const [ultimoRegistro, setUltimoRegistro] = useState(null);
  const [scannedData, setScannedData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [user, setUser] = useState(null);

  useEffect(() => {
    cargarDatos();
    setUser(getCurrentUser());
  }, []);

  const cargarDatos = async () => {
    setLoading(true);
    try {
      const [jugadoresData, entrenamientosData, partidosData, pagosData] = await Promise.all([
        getJugadores(),
        getEntrenamientos(),
        getPartidos(),
        getPagos()
      ]);
      setJugadores(jugadoresData);
      setEntrenamientos(entrenamientosData);
      setPartidos(partidosData);
      setPagos(pagosData);
    } catch (error) {
      console.error('Error cargando datos:', error);
      alert('Error al cargar los datos');
    }
    setLoading(false);
  };

  // Función para enviar correo de confirmación de pago
  const enviarCorreoPago = async (email, nombre, monto, evento, tipo) => {
    try {
      const response = await fetch('http://localhost:5001/api/enviar-notificacion-pago', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          email,
          nombre,
          monto,
          evento: evento.nombre || evento.rival,
          fecha: evento.fecha,
          tipo
        })
      });
      
      if (response.ok) {
        console.log('✅ Correo de pago enviado a:', email);
      }
    } catch (error) {
      console.error('Error enviando correo de pago:', error);
    }
  };

  const handleScan = async (result) => {
    if (result && !loading) {
      const qrText = result?.text || result;
      setScanResult(qrText);
      await procesarQR(qrText);
      setShowScanner(false);
    }
  };

  const handleError = (err) => {
    console.error(err);
    alert('Error al leer el QR. Asegúrate de que el código sea visible.');
  };

  const preguntarPago = (jugadorNombre, eventoNombre, monto, tipo) => {
    return window.confirm(
      `📋 JUGADOR: ${jugadorNombre}\n` +
      `🏆 EVENTO: ${eventoNombre}\n` +
      `💰 MONTO A PAGAR: $${monto}\n\n` +
      `¿El jugador ya realizó el pago?\n` +
      `(Presiona OK si ya pagó, Cancelar si aún debe)`
    );
  };

  const procesarQR = async (qrText) => {
    setLoading(true);
    
    // Buscar jugador por QR code
    const jugador = jugadores.find(j => j.qr_code === qrText || j.id?.toString() === qrText);
    
    if (!jugador) {
      alert('❌ Jugador no encontrado. Verifica que el QR sea válido.');
      setLoading(false);
      return;
    }

    if (!eventoSeleccionado.id) {
      alert('⚠️ Primero selecciona un entrenamiento o partido');
      setLoading(false);
      return;
    }

    let resultado = null;
    let montoEvento = 0;
    let eventoNombre = '';

    try {
      if (eventoSeleccionado.tipo === 'entrenamiento') {
        const entrenamiento = entrenamientos.find(e => e.id === eventoSeleccionado.id);
        
        if (!entrenamiento) {
          alert('❌ Entrenamiento no encontrado');
          setLoading(false);
          return;
        }

        montoEvento = entrenamiento.monto_pago || 0;
        eventoNombre = `Entrenamiento del ${new Date(entrenamiento.fecha).toLocaleDateString('es-ES')}`;

        const asistencia = await getAsistenciaEntrenamientos();
        const registro = asistencia.find(a => 
          a.entrenamiento_id === eventoSeleccionado.id && 
          a.jugador_id === jugador.id
        );

        if (!registro || registro.estado !== 'apuntado') {
          alert(`⚠️ ${jugador.nombre} no está apuntado para este entrenamiento`);
          setLoading(false);
          return;
        }

        if (registro.estado === 'asistio') {
          alert(`ℹ️ ${jugador.nombre} ya registró su asistencia a este entrenamiento`);
          setLoading(false);
          return;
        }

        // Preguntar por el pago si hay monto
        let pagoRealizado = false;
        if (montoEvento > 0) {
          pagoRealizado = preguntarPago(jugador.nombre, eventoNombre, montoEvento, 'entrenamiento');
          
          if (pagoRealizado) {
            // Buscar pago pendiente y marcarlo como pagado
            const pagoPendiente = pagos.find(p => 
              p.jugador_id === jugador.id && 
              p.concepto === 'entrenamiento' && 
              p.referencia_id === eventoSeleccionado.id &&
              p.estado === 'pendiente'
            );
            
            if (pagoPendiente) {
              await registrarPago(pagoPendiente.id, 'qr');
              await enviarCorreoPago(jugador.email, jugador.nombre, montoEvento, entrenamiento, 'entrenamiento');
            }
          }
        }

        // Registrar asistencia
        await updateAsistenciaEntrenamiento(eventoSeleccionado.id, jugador.id, 'asistio', true);
        
        resultado = {
          jugador,
          evento: entrenamiento,
          tipo: 'entrenamiento',
          asistencia: 'asistio',
          pagoRealizado,
          monto: montoEvento
        };
        
      } else if (eventoSeleccionado.tipo === 'partido') {
        const partido = partidos.find(p => p.id === eventoSeleccionado.id);
        
        if (!partido) {
          alert('❌ Partido no encontrado');
          setLoading(false);
          return;
        }

        montoEvento = partido.monto_pago || 0;
        eventoNombre = `Partido vs ${partido.rival} - ${new Date(partido.fecha).toLocaleDateString('es-ES')}`;

        const asistencia = await getAsistenciaPartidos();
        const registro = asistencia.find(a => 
          a.partido_id === eventoSeleccionado.id && 
          a.jugador_id === jugador.id
        );

        if (!registro || registro.estado !== 'convocado') {
          alert(`⚠️ ${jugador.nombre} no está convocado para este partido`);
          setLoading(false);
          return;
        }

        if (registro.estado === 'jugo') {
          alert(`ℹ️ ${jugador.nombre} ya registró su asistencia a este partido`);
          setLoading(false);
          return;
        }

        // Preguntar por el pago si hay monto
        let pagoRealizado = false;
        if (montoEvento > 0) {
          pagoRealizado = preguntarPago(jugador.nombre, eventoNombre, montoEvento, 'partido');
          
          if (pagoRealizado) {
            // Buscar pago pendiente y marcarlo como pagado
            const pagoPendiente = pagos.find(p => 
              p.jugador_id === jugador.id && 
              p.concepto === 'partido' && 
              p.referencia_id === eventoSeleccionado.id &&
              p.estado === 'pendiente'
            );
            
            if (pagoPendiente) {
              await registrarPago(pagoPendiente.id, 'qr');
              await enviarCorreoPago(jugador.email, jugador.nombre, montoEvento, partido, 'partido');
            }
          }
        }

        // Verificar buseta y campos
        if (partido.hay_buseta && registro.campos > 0) {
          const totalBuseta = registro.campos * (partido.valor_campo || 0);
          if (totalBuseta > 0) {
            const pagoBuseta = preguntarPago(jugador.nombre, `Buseta para ${eventoNombre}`, totalBuseta, 'buseta');
            if (pagoBuseta) {
              alert(`✅ Pago de buseta (${totalBuseta}) registrado`);
            }
          }
        }

        // Registrar asistencia
        await updateAsistenciaPartido(eventoSeleccionado.id, jugador.id, 'jugo', true);
        
        resultado = {
          jugador,
          evento: partido,
          tipo: 'partido',
          asistencia: 'jugo',
          pagoRealizado,
          monto: montoEvento
        };
      }

      if (resultado) {
        setScannedData(resultado);
        
        let fechaStr = 'Fecha no disponible';
        if (resultado.evento.fecha) {
          const fechaObj = new Date(resultado.evento.fecha);
          if (!isNaN(fechaObj.getTime())) {
            fechaStr = fechaObj.toLocaleDateString('es-ES');
          }
        }
        
        setUltimoRegistro({
          jugador: resultado.jugador.nombre,
          evento: resultado.tipo === 'entrenamiento' ? `Entrenamiento del ${fechaStr}` : `Partido vs ${resultado.evento.rival}`,
          hora: new Date().toLocaleTimeString(),
          pago: resultado.pagoRealizado ? 'Pagado' : (resultado.monto > 0 ? 'Pendiente' : 'Sin pago')
        });
        
        let mensaje = `✅ ${resultado.jugador.nombre} registró su asistencia al ${resultado.tipo === 'entrenamiento' ? 'entrenamiento' : 'partido'}`;
        if (resultado.monto > 0) {
          if (resultado.pagoRealizado) {
            mensaje += `\n💰 Pago de $${resultado.monto} registrado correctamente. Se ha enviado el comprobante al correo.`;
          } else {
            mensaje += `\n⚠️ El jugador tiene un pago pendiente de $${resultado.monto}`;
          }
        }
        alert(mensaje);
        
        await cargarDatos();
      }
    } catch (error) {
      console.error('Error procesando QR:', error);
      alert('Error al procesar el QR: ' + error.message);
    }
    
    setLoading(false);
  };

  const formatearFecha = (fecha) => {
    if (!fecha) return 'Fecha no asignada';
    try {
      const fechaObj = new Date(fecha);
      if (!isNaN(fechaObj.getTime())) {
        return fechaObj.toLocaleDateString('es-ES');
      }
      return fecha;
    } catch (e) {
      return 'Fecha inválida';
    }
  };

  const eventosDisponibles = () => {
    const eventos = [];
    
    entrenamientos.forEach(e => {
      eventos.push({ 
        id: e.id, 
        tipo: 'entrenamiento', 
        nombre: `Entrenamiento - ${formatearFecha(e.fecha)}`, 
        lugar: e.lugar, 
        fecha: e.fecha,
        monto: e.monto_pago
      });
    });
    
    partidos.forEach(p => {
      eventos.push({ 
        id: p.id, 
        tipo: 'partido', 
        nombre: `Partido vs ${p.rival} - ${formatearFecha(p.fecha)}`, 
        lugar: p.lugar, 
        fecha: p.fecha,
        monto: p.monto_pago,
        hay_buseta: p.hay_buseta
      });
    });
    
    return eventos.sort((a, b) => {
      if (!a.fecha && !b.fecha) return 0;
      if (!a.fecha) return 1;
      if (!b.fecha) return -1;
      return new Date(a.fecha) - new Date(b.fecha);
    });
  };

  const handleEventoChange = (e) => {
    if (!e.target.value) {
      setEventoSeleccionado({ tipo: 'entrenamiento', id: null });
      return;
    }
    const [tipo, id] = e.target.value.split('_');
    setEventoSeleccionado({ tipo, id: parseInt(id) });
  };

  const getNombre = (obj) => obj?.nombre || 'Desconocido';
  const getNumeroCamiseta = (obj) => obj?.numero_camiseta || '?';
  const getFechaEvento = (evento) => formatearFecha(evento?.fecha);
  const getHoraEvento = (evento) => evento?.hora || '--:--';

  if (loading && jugadores.length === 0) {
    return (
      <div className="escaner-qr">
        <div className="loading-container">Cargando datos...</div>
      </div>
    );
  }

  return (
    <div className="escaner-qr">
      <div className="header-actions">
        <h2><i className="fas fa-qrcode"></i> Escáner QR - Control de Asistencia</h2>
      </div>

      <div className="escaner-container">
        <div className="selector-evento">
          <label><i className="fas fa-calendar-alt"></i> Seleccionar evento:</label>
          <select onChange={handleEventoChange} value={eventoSeleccionado.id ? `${eventoSeleccionado.tipo}_${eventoSeleccionado.id}` : ''}>
            <option value="">-- Seleccionar entrenamiento o partido --</option>
            {eventosDisponibles().map(evento => (
              <option key={`${evento.tipo}_${evento.id}`} value={`${evento.tipo}_${evento.id}`}>
                {evento.nombre} - {evento.lugar} {evento.monto > 0 ? `($${evento.monto})` : ''}
              </option>
            ))}
          </select>
        </div>

        {eventoSeleccionado.id && (
          <div className="evento-info">
            <i className="fas fa-info-circle"></i>
            <span>
              Escaneando asistencia para: <strong>
                {eventoSeleccionado.tipo === 'entrenamiento' 
                  ? `Entrenamiento del ${formatearFecha(entrenamientos.find(e => e.id === eventoSeleccionado.id)?.fecha)}`
                  : `Partido vs ${partidos.find(p => p.id === eventoSeleccionado.id)?.rival}`}
              </strong>
            </span>
          </div>
        )}

        <div className="scanner-area">
          {!showScanner ? (
            <div className="scanner-placeholder">
              <i className="fas fa-camera"></i>
              <p>Haz clic en "Iniciar Escáner" para comenzar</p>
              <button 
                className="btn-iniciar-scanner" 
                onClick={() => setShowScanner(true)}
                disabled={!eventoSeleccionado.id}
              >
                <i className="fas fa-play"></i> Iniciar Escáner
              </button>
              {!eventoSeleccionado.id && (
                <p className="warning">⚠️ Primero selecciona un evento</p>
              )}
            </div>
          ) : (
            <div className="scanner-active">
              <div className="scanner-header">
                <span><i className="fas fa-qrcode"></i> Escaneando...</span>
                <button className="btn-cerrar-scanner" onClick={() => setShowScanner(false)}>
                  <i className="fas fa-times"></i>
                </button>
              </div>
              <div className="qr-reader-container">
                <QrReader
                  onResult={handleScan}
                  constraints={{ facingMode: 'environment' }}
                  containerStyle={{ width: '100%' }}
                  videoStyle={{ width: '100%', borderRadius: '1rem' }}
                />
              </div>
              <p className="instrucciones">
                <i className="fas fa-mobile-alt"></i> Coloca el código QR del jugador frente a la cámara
              </p>
            </div>
          )}
        </div>

        {ultimoRegistro && (
          <div className="ultimo-registro">
            <h3><i className="fas fa-history"></i> Último registro</h3>
            <div className="registro-info">
              <p><strong>Jugador:</strong> {ultimoRegistro.jugador}</p>
              <p><strong>Evento:</strong> {ultimoRegistro.evento}</p>
              <p><strong>Hora:</strong> {ultimoRegistro.hora}</p>
              <p><strong>Estado pago:</strong> {ultimoRegistro.pago}</p>
            </div>
          </div>
        )}

        {scannedData && (
          <div className="detalle-asistencia">
            <h3><i className="fas fa-check-circle"></i> Detalle de asistencia</h3>
            <div className="detalle-info">
              <div className="detalle-item">
                <i className="fas fa-user"></i>
                <span>{getNombre(scannedData.jugador)} (#{getNumeroCamiseta(scannedData.jugador)})</span>
              </div>
              <div className="detalle-item">
                <i className="fas fa-futbol"></i>
                <span>{scannedData.tipo === 'entrenamiento' ? 'Entrenamiento' : 'Partido'}</span>
              </div>
              <div className="detalle-item">
                <i className="fas fa-calendar"></i>
                <span>{getFechaEvento(scannedData.evento)}</span>
              </div>
              <div className="detalle-item">
                <i className="fas fa-clock"></i>
                <span>{getHoraEvento(scannedData.evento)} hrs</span>
              </div>
              <div className="detalle-item estado">
                <i className="fas fa-check-circle"></i>
                <span className="asistio">Asistencia registrada ✓</span>
              </div>
              {scannedData.monto > 0 && (
                <div className={`detalle-item ${scannedData.pagoRealizado ? 'pago-realizado' : 'pago-pendiente'}`}>
                  <i className="fas fa-dollar-sign"></i>
                  <span className={scannedData.pagoRealizado ? 'realizado' : 'pendiente'}>
                    {scannedData.pagoRealizado ? `Pago de $${scannedData.monto} realizado ✓` : `Pago pendiente: $${scannedData.monto}`}
                  </span>
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default EscanerQR;
